    if (!sheet) return;
    const show = ++this.shows;
    try {
      const lines = await this.api.lines(sheet, this.filter());
      if (show === this.shows) this.lines.set(lines);
    } catch {
      if (show === this.shows) this.error.set('The audit lines could not be read.');
    }
  }
}
